#!/usr/bin/env python3
"""Separate native llama.cpp throughput probe; never substitute for benchmark logs."""
import datetime,hashlib,json,pathlib,resource,time
import llama_cpp
from llama_cpp import Llama
ROOT=pathlib.Path(__file__).resolve().parent
OUT=ROOT/'speed_probe';OUT.mkdir(exist_ok=True)
if (OUT/'records.jsonl').exists():raise RuntimeError('Refusing overwrite of previous speed probe')
source=[json.loads(s) for s in (ROOT/'run_02/records.jsonl').read_text().splitlines()]
# Fixed first task, both original prompt protocols, independent of its accuracy.
rows=source[:2]
manifest={'started_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'kind':'separate_native_throughput_probe','source_run':'run_02','source_records_sha256':hashlib.sha256((ROOT/'run_02/records.jsonl').read_bytes()).hexdigest(),'model_id':rows[0]['model'],'model_revision':rows[0]['model_revision'],'quantization':'Q4_K_M','engine':'llama-cpp-python','engine_version':llama_cpp.__version__,'n_ctx':4096,'n_batch':512,'n_ubatch':512,'n_threads':4,'n_threads_batch':4,'n_gpu_layers':0,'no_perf':False,'use_mmap':True,'parameters':rows[0]['parameters'],'case_selection':'First task of the fixed run_02, direct and cot, without accuracy-based selection','native_timing_source':'llama_cpp.llama_perf_context(llm._ctx.ctx), explicitly reset before each call','warmup':'No separate warm-up. KV state and performance counters reset before each measured call. OS file cache not cleared.','interpretation':'n_eval/t_eval_ms measures native backend token evaluation during autoregressive decoding. It excludes prompt prefill and may exclude Python/sampling overhead; use native counts, which can differ from returned completion token count. Not the end-to-end output rate.','sample_size':2,'paid_api_calls':0}
(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
t=time.perf_counter();llm=Llama(model_path=str(ROOT/'qwen7b/qwen2.5-7b-instruct-q4_k_m-00001-of-00002.gguf'),n_ctx=4096,n_batch=512,n_ubatch=512,n_threads=4,n_threads_batch=4,n_gpu_layers=0,seed=42,use_mmap=True,no_perf=False,verbose=False);manifest['model_loading_seconds']=time.perf_counter()-t
results=[]
with (OUT/'records.jsonl').open('w',buffering=1) as f:
 for prior in rows:
  prompt=prior['rendered_prompt'];llm.reset();llama_cpp.llama_perf_context_reset(llm._ctx.ctx)
  start=time.perf_counter();response=llm(prompt,**prior['parameters']);elapsed=time.perf_counter()-start
  data=llama_cpp.llama_perf_context(llm._ctx.ctx);raw={name:getattr(data,name) for name,_ in data._fields_}
  assert raw['n_eval']>0 and raw['t_eval_ms']>0 and raw['n_p_eval']>0 and raw['t_p_eval_ms']>0,'Native perf counters missing'
  result={'id':prior['id'],'protocol':prior['protocol'],'model':prior['model'],'model_revision':prior['model_revision'],'parameters':prior['parameters'],'rendered_prompt':prompt,'prompt_sha256':hashlib.sha256(prompt.encode()).hexdigest(),'latency_seconds':elapsed,'raw_output':response['choices'][0]['text'],'token_usage':response['usage'],'finish_reason':response['choices'][0]['finish_reason'],'raw_native_counters':raw,'prefill_tokens_per_second_native':1000*raw['n_p_eval']/raw['t_p_eval_ms'],'decode_tokens_per_second_native':1000*raw['n_eval']/raw['t_eval_ms'],'output_tokens_per_second_end_to_end':response['usage']['completion_tokens']/elapsed,'output_matches_original_run':response['choices'][0]['text']==prior['raw_output']}
  results.append(result);f.write(json.dumps(result,ensure_ascii=False)+'\n');f.flush();print(json.dumps({k:v for k,v in result.items() if k not in ['rendered_prompt']},ensure_ascii=False),flush=True)
summary={'sample_size':len(results),'decode_tokens_per_second_native_aggregate':1000*sum(r['raw_native_counters']['n_eval'] for r in results)/sum(r['raw_native_counters']['t_eval_ms'] for r in results),'prefill_tokens_per_second_native_aggregate':1000*sum(r['raw_native_counters']['n_p_eval'] for r in results)/sum(r['raw_native_counters']['t_p_eval_ms'] for r in results),'output_tokens_per_second_end_to_end_aggregate':sum(r['token_usage']['completion_tokens'] for r in results)/sum(r['latency_seconds'] for r in results),'native_decode_tokens_total':sum(r['raw_native_counters']['n_eval'] for r in results),'native_decode_ms_total':sum(r['raw_native_counters']['t_eval_ms'] for r in results),'native_prefill_tokens_total':sum(r['raw_native_counters']['n_p_eval'] for r in results),'native_prefill_ms_total':sum(r['raw_native_counters']['t_p_eval_ms'] for r in results),'all_outputs_match_original_run':all(r['output_matches_original_run'] for r in results),'interpretation':manifest['interpretation'],'limitations':['Two prompts only, one input task, this CPU and quantized backend.','Native decode throughput is not end-to-end response speed.','Benchmark run_02 metrics remain unchanged.']}
(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');manifest['completed_at_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();manifest['peak_process_rss_kib']=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss;manifest['records_sha256']=hashlib.sha256((OUT/'records.jsonl').read_bytes()).hexdigest();(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
